    const G = Game, fr = G.frame, other = att && att !== v;
    if (v.fPro >= 5) v.hitstun = Math.floor(v.hitstun * Math.max(0.55, 1 - 0.06 * (v.fPro - 4)));
    const proj = !hb.f && !!hb.radial;
