    const it = { kind, x, y: def.floating ? -200 : st.blast.t + 160, vx: def.floating ? rand(-1.5, 1.5) : 0, vy: 0, age: 0, baseY: -190, hp: def.hp || 0, ammo };
    G.items.push(it);
