    // online play it comes out of the box as a real pistol instead (same spawn roll, same slot).
    for (const it of G.items) if (it.kind === 'raygun' && !it.gnSeen) { it.gnSeen = 1; it.kind = 'pistol'; it.ammo = this.DEF.pistol.mag; }
